import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {randomUUID,createHash}from'node:crypto';import{setTimeout as delay}from'node:timers/promises';import{setGlobalProxyFromEnv}from'node:http';import{query,decode}from'../../test/helpers/dns-wire.mjs';
process.env.HTTP_PROXY=process.env.HTTPS_PROXY='http://127.0.0.1:7889';setGlobalProxyFromEnv();const dir=import.meta.dirname,mode=process.argv[2];assert.ok(['round1','round2','cleanup'].includes(mode));
const file=path.join(dir,'ledger-private.json');const save=()=>fs.writeFileSync(file,JSON.stringify(ledger,null,2));
const ledger=fs.existsSync(file)?JSON.parse(fs.readFileSync(file)): {cap:60,attempts:[],createdAt:new Date().toISOString(),sources:'controlled fixture only',profileEndpointAttempts:1};
const cfg=JSON.parse(fs.readFileSync(path.join(dir,mode==='cleanup'?'cleanup-control.json':'control.json')));assert.equal(ledger.cap,60);
const origin='https://superdoh.aloneowo0.workers.dev',fixture='https://superdoh-dns-cpu-fixtures-20261024.aloneowo0.workers.dev';
const wire=query('example.com',65),ech=Buffer.from('AD7+DQA6AQAgACABAgMEBQYHCAkKCwwNDg8QERITFBUWFxgZGhscHR4fIAAEAAEAAQALZXhhbXBsZS5jb20AAA==','base64');
async function request(label,phase,i,target=origin){
 assert.ok(ledger.attempts.length<60);if(ledger.lastCompletedAt)await delay(Math.max(0,1050-(Date.now()-ledger.lastCompletedAt)));
 const row={sampleId:randomUUID(),label,phase,index:i,version:cfg.version,startedAt:new Date().toISOString()};ledger.attempts.push(row);save();const start=performance.now();
 try{const r=await fetch(target+'/dns-query',{method:'POST',headers:{'Content-Type':'application/dns-message','X-Acceptance-Sample-Id':row.sampleId},body:wire,redirect:'error',signal:AbortSignal.timeout(15000)});row.httpStatus=r.status;row.responseVersion=r.headers.get('X-Acceptance-Version');row.colo=r.headers.get('cf-ray')?.split('-').at(-1);
 const chunks=[];let size=0;const reader=r.body.getReader();try{while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>65535){await reader.cancel();throw Error('RESPONSE_BOUND');}chunks.push(value);}}finally{reader.releaseLock();}const b=Buffer.concat(chunks);row.responseSha256=createHash('sha256').update(b).digest('hex');
 if(mode==='cleanup'&&target===fixture){assert.equal(r.status,503);row.correct=true;return;}
 assert.equal(r.status,200);const d=decode(b);assert.equal(d.id,0x4242);assert.deepEqual(d.questions,[{name:'example.com',type:65,class:1}]);row.dnsRcode=d.flags&15;
 if(mode==='cleanup'){assert.equal(d.flags&15,2);assert.equal(d.records.filter(r=>r.section===0).length,0);row.correct=true;return;}
 assert.equal(row.responseVersion,cfg.version);assert.equal(d.flags&15,0);assert.equal(d.flags&32,0);const a=d.records.filter(r=>r.section===0),add=d.records.filter(r=>r.section===2);assert.equal(a.length,1);assert.equal(a[0].type,65);assert.equal(a[0].ttl,17);assert.deepEqual(a[0].data,[0,1,0,0,3,0,2,1,187,0,5,0,ech.length,...ech]);assert.equal(add.length,1);assert.equal(add[0].type,1);assert.equal(add[0].ttl,17);assert.deepEqual(add[0].data,[192,0,2,8]);row.correct=true;
 }catch(e){row.correct=false;row.error=e.code??'REQUEST_ASSERTION_OR_TRANSPORT_FAILED';throw e;}finally{row.clientLatencyMs=performance.now()-start;row.finishedAt=new Date().toISOString();ledger.lastCompletedAt=Date.now();save();}
}
if(mode==='cleanup'){await request('producer-restored','cleanup',0);await request('fixture-restored','cleanup',0,fixture);console.log(JSON.stringify({event:'CLEANUP_VERIFIED',attempts:ledger.attempts.length}));}
else{assert.equal(cfg.label,mode);console.log(JSON.stringify({event:'ROUND_START',label:mode,version:cfg.version}));for(let i=0;i<16;i++)await request(mode,'warmup',i);if(mode==='round2'){console.log(JSON.stringify({event:'PROFILE_READY',version:cfg.version}));const end=Date.now()+180000;while(!fs.existsSync(path.join(dir,'capture-go'))){if(fs.existsSync(path.join(dir,'stop'))||Date.now()>end)throw Error('PROFILE_GATE_STOPPED');await delay(250);}await delay(2000);}for(let i=0;i<38;i++){if(fs.existsSync(path.join(dir,'stop')))throw Error('STOP_REQUESTED');await request(mode,'measured',i);}console.log(JSON.stringify({event:'ROUND_COMPLETE',label:mode,attempts:ledger.attempts.length}));}
